-- Idioms (成语) for the idiom drag-and-drop game.
--
-- One row per four-character idiom. The rows are generated by
-- `scripts/build-idioms.ts` from `data/idioms.json` and imported by
-- `scripts/import-idioms.ts`.
--
-- The reading is stored per character rather than as one blob, because the
-- game shows the reading of the character being dragged, and a character can
-- have more than one reading (行 xíng / háng). One column per position
-- keeps each position's reading unambiguous.
--
-- `chars.pinyin` could not be reused: the 2026-06-17 content migration
-- emptied that column for every row, so a join against it returns nothing.
-- These readings come from pinyin-pro — the same source
-- `lib/pinyin-index.ts::resolvePinyin` uses — so they cannot disagree with
-- the readings shown on the dictionary page.
--
-- Idempotent: CREATE TABLE IF NOT EXISTS short-circuits on re-run, and the
-- importer upserts on the primary key, so re-importing is a no-op.

CREATE TABLE IF NOT EXISTS idioms (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  word         VARCHAR(16)  NOT NULL,
  pinyin       VARCHAR(64)  NOT NULL DEFAULT '',
  meaning      VARCHAR(512) NOT NULL DEFAULT '',
  level        TINYINT(4)   NOT NULL DEFAULT 1,
  category     VARCHAR(32)  NOT NULL DEFAULT '',
  created_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_idioms_word (word),
  KEY idx_idioms_level (level),
  KEY idx_idioms_category (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
